package org.wangshu.ime;

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

/** Synthetic host only. No Android API, clipboard, filesystem, or personal content. */
public final class BoundEditorChecks {
 static int checks;
 static void check(boolean v,String text){if(!v)throw new AssertionError(text);checks++;}
 static final class Doc {String text="XSAFE";int start=1,end=1;}
 static final class Fake implements BoundEditorPrototype.Host {
  Object owner=new Object();long session=1;boolean allowed=true;Doc first=new Doc(),second=new Doc(),active=first;
  Runnable onRead,onSelect,onBeforeCommit,onAfterCommit;boolean failSelect,failCommit,throwAfterCommit;int reads,selects,commits;Object lastOwner;
  public long session(){return session;}public Object connection(){return owner;}public boolean allowed(){return allowed;}
  public BoundEditorPrototype.Snapshot read(Object c){lastOwner=c;reads++;BoundEditorPrototype.Snapshot snap=new BoundEditorPrototype.Snapshot(active.text,active.start,active.end);if(onRead!=null){Runnable x=onRead;onRead=null;x.run();}return snap;}
  public boolean select(Object c,int start,int end){lastOwner=c;selects++;active.start=start;active.end=end;if(onSelect!=null){Runnable x=onSelect;onSelect=null;x.run();}return !failSelect;}
  public boolean commit(Object c,String v){lastOwner=c;commits++;if(onBeforeCommit!=null){Runnable x=onBeforeCommit;onBeforeCommit=null;x.run();}Doc d=active;d.text=d.text.substring(0,d.start)+v+d.text.substring(d.end);d.start=d.end=d.start+v.length();if(onAfterCommit!=null){Runnable x=onAfterCommit;onAfterCommit=null;x.run();}if(throwAfterCommit)throw new IllegalStateException("synthetic commit exception");return !failCommit;}
 }
 static BoundEditorPrototype make(Fake f){BoundEditorPrototype x=BoundEditorPrototype.capture(f);check(x!=null,"capture");return x;}
 static void normal(){Fake f=new Fake();Object owner=f.owner;BoundEditorPrototype b=make(f);var s=b.snapshot();check(s!=null,"snapshot");check(b.replace(s,1,1,"A",2)==BoundEditorPrototype.Outcome.ACCEPTED,"normal accept");check(f.first.text.equals("XASAFE")&&f.lastOwner==owner&&f.commits==1,"captured owner receives insert once");check(b.replace(s,1,1,"A",2)==BoundEditorPrototype.Outcome.BLOCKED&&f.commits==1,"one shot");}
 static void ownerChanged(){Fake f=new Fake();BoundEditorPrototype b=make(f);var s=b.snapshot();f.owner=new Object();f.active=f.second;check(b.replace(s,1,1,"A",2)==BoundEditorPrototype.Outcome.BLOCKED,"identical new connection blocked");check(f.selects==0&&f.commits==0&&f.second.text.equals("XSAFE"),"new editor untouched");}
 static void reusedConnectionNewSession(){Fake f=new Fake();BoundEditorPrototype b=make(f);var s=b.snapshot();f.session++;f.active=f.second;check(b.replace(s,1,1,"A",2)==BoundEditorPrototype.Outcome.BLOCKED,"same connection new session blocked");check(f.commits==0&&f.second.text.equals("XSAFE"),"reused connection caused no write");}
 static void privateField(){Fake f=new Fake();BoundEditorPrototype b=make(f);var s=b.snapshot();f.allowed=false;check(b.replace(s,1,1,"A",2)==BoundEditorPrototype.Outcome.BLOCKED&&f.commits==0,"private mode blocks mutation");}
 static void switchingDuringRead(){Fake f=new Fake();BoundEditorPrototype b=make(f);f.onRead=()->{f.session++;f.active=f.second;};check(b.snapshot()==null,"reentrant session change discards snapshot");check(f.commits==0,"read switch causes no commit");}
 static void snapshotReentry(){Fake f=new Fake();BoundEditorPrototype b=make(f);var initial=b.snapshot();final BoundEditorPrototype.Outcome[] nested={null};f.onRead=()->nested[0]=b.replace(initial,1,1,"A",2);var next=b.snapshot();check(next!=null&&nested[0]==BoundEditorPrototype.Outcome.BUSY&&f.commits==0,"snapshot reentry cannot mutate");check(b.replace(initial,1,1,"A",2)==BoundEditorPrototype.Outcome.ACCEPTED&&f.commits==1,"snapshot guard releases for later operation");}
 static void selectionChanged(){Fake f=new Fake();BoundEditorPrototype b=make(f);var s=b.snapshot();f.first.start=f.first.end=2;check(b.replace(s,1,1,"A",2)==BoundEditorPrototype.Outcome.BLOCKED&&f.commits==0&&f.selects==0,"changed caret blocked before mutation");}
 static void privateDuringSnapshot(){Fake f=new Fake();BoundEditorPrototype b=make(f);f.onRead=()->f.allowed=false;check(b.snapshot()==null,"snapshot discarded after privacy transition");f.allowed=true;check(b.replace(new BoundEditorPrototype.Snapshot("XSAFE",1,1),1,1,"A",2)==BoundEditorPrototype.Outcome.BLOCKED&&f.commits==0,"privacy transition closes token");}
 static void reenterDuringSelect(){Fake f=new Fake();BoundEditorPrototype b=make(f);var s=b.snapshot();final BoundEditorPrototype.Outcome[] nested={null};f.onSelect=()->nested[0]=b.replace(s,1,1,"A",2);check(b.replace(s,1,1,"A",2)==BoundEditorPrototype.Outcome.ACCEPTED,"outer committed");check(nested[0]==BoundEditorPrototype.Outcome.BUSY&&f.commits==1&&f.first.text.equals("XASAFE"),"reentrant write blocked");}
 static void switchAfterSelection(){Fake f=new Fake();BoundEditorPrototype b=make(f);var s=b.snapshot();f.onSelect=()->{f.session++;f.active=f.second;};check(b.replace(s,1,1,"A",2)==BoundEditorPrototype.Outcome.UNCERTAIN,"post-selection switch is uncertain");check(f.commits==0&&f.second.text.equals("XSAFE"),"no commit to new editor");check(b.replace(s,1,1,"A",2)==BoundEditorPrototype.Outcome.BLOCKED,"no retry after partial operation");}
 static void appliedThenThrow(){Fake f=new Fake();BoundEditorPrototype b=make(f);var s=b.snapshot();f.throwAfterCommit=true;check(b.replace(s,1,1,"A",2)==BoundEditorPrototype.Outcome.UNCERTAIN,"applied then throw uncertain");check(f.first.text.equals("XASAFE")&&f.commits==1,"effect is not rolled back or retried");check(b.replace(s,1,1,"A",2)==BoundEditorPrototype.Outcome.BLOCKED&&f.commits==1,"no replay");}
 static void outsideEditBefore(){Fake f=new Fake();BoundEditorPrototype b=make(f);var s=b.snapshot();f.first.text="XDIFF";check(b.replace(s,1,1,"A",2)==BoundEditorPrototype.Outcome.BLOCKED,"changed surrounding text blocked");check(f.selects==0&&f.commits==0,"no edit after mismatch");}
 static void outsideEditAfterSelection(){Fake f=new Fake();BoundEditorPrototype b=make(f);var s=b.snapshot();f.onSelect=()->f.first.text="XDIFF";check(b.replace(s,1,1,"A",2)==BoundEditorPrototype.Outcome.UNCERTAIN,"external edit after selection uncertain");check(f.commits==0,"post-selection snapshot blocks commit");}
 static void mutationBetweenCheckAndCommit(){Fake f=new Fake();BoundEditorPrototype b=make(f);var s=b.snapshot();f.onBeforeCommit=()->f.first.text="XDIFF";check(b.replace(s,1,1,"A",2)==BoundEditorPrototype.Outcome.UNCERTAIN,"postcheck notices altered document");check(f.first.text.equals("XADIFF")&&f.commits==1,"uncertain result cannot undo already-issued mutation");}
 static void concurrent()throws Exception{Fake f=new Fake();BoundEditorPrototype b=make(f);var s=b.snapshot();CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);f.onSelect=()->{entered.countDown();try{if(!release.await(3,TimeUnit.SECONDS))throw new AssertionError("timeout");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}};AtomicReference<BoundEditorPrototype.Outcome> first=new AtomicReference<>();Thread t=new Thread(()->first.set(b.replace(s,1,1,"A",2)));t.start();check(entered.await(3,TimeUnit.SECONDS),"first entered select");check(b.snapshot()==null,"no concurrent snapshot");BoundEditorPrototype.Outcome second=b.replace(s,1,1,"A",2);release.countDown();t.join(3000);check(!t.isAlive()&&first.get()==BoundEditorPrototype.Outcome.ACCEPTED,"first concurrent operation completed");check(second==BoundEditorPrototype.Outcome.BUSY&&f.commits==1,"second concurrent operation blocked");check(b.replace(s,1,1,"A",2)==BoundEditorPrototype.Outcome.BLOCKED&&f.commits==1,"completed token cannot be replayed");}
 static void silentWrapperRetarget(){Fake f=new Fake();BoundEditorPrototype b=make(f);var s=b.snapshot();f.onBeforeCommit=()->f.active=f.second;BoundEditorPrototype.Outcome result=b.replace(s,1,1,"A",2);check(result==BoundEditorPrototype.Outcome.ACCEPTED&&f.first.text.equals("XSAFE")&&f.second.text.equals("XASAFE"),"fixture must demonstrate invisible retarget");System.out.println("KNOWN LIMITATION: same connection object and session silently retargeted before commit; identity guard cannot detect wrong editor");}
 public static void main(String[] args)throws Exception{normal();ownerChanged();reusedConnectionNewSession();privateField();switchingDuringRead();snapshotReentry();selectionChanged();privateDuringSnapshot();reenterDuringSelect();switchAfterSelection();appliedThenThrow();outsideEditBefore();outsideEditAfterSelection();mutationBetweenCheckAndCommit();concurrent();silentWrapperRetarget();System.out.println("PASS "+checks+" synthetic protocol checks; one deliberate limitation demonstrated; no Android or production integration");}
}
